import pandas as pd
import re

file_path = '/data/mixed_units_register.xlsx'
df_raw = pd.read_excel(file_path, sheet_name='Disbursement Register', header=None)
header_row = df_raw.iloc[5]
data = df_raw.iloc[6:].copy()
data.columns = header_row
data.columns = [str(c).strip() for c in data.columns]

# Filter valid record IDs
mask = data['Record ID'].notna() & data['Record ID'].astype(str).str.startswith('MU-')
data_valid = data[mask].copy()

def parse_amount(val):
    if pd.isna(val):
        return 0.0
    s = str(val).strip()
    if s in ('', '-', 'NA', 'NaN', 'nan'):
        return 0.0
    s = s.replace('₹', '').replace(',', '').strip()
    s_low = s.lower()
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([a-zA-Z]*)$', s_low)
    if m:
        num_str, unit = m.groups()
        try:
            num = float(num_str)
        except:
            return 0.0
        unit = unit.strip()
        if unit in ('', 'inr'):
            mult = 1
        elif unit in ('l', 'lakh'):
            mult = 100000
        elif unit in ('cr', 'crore'):
            mult = 10000000
        elif unit in ('k', 'thousand'):
            mult = 1000
        else:
            mult = 1
        return num * mult
    else:
        try:
            return float(s)
        except:
            return 0.0

data_valid['Amount_parsed'] = data_valid['Amount'].apply(parse_amount)

print('Valid rows:', len(data_valid))
print(data_valid.head(10)[['Record ID','Amount','Amount_parsed']])
print(data_valid.tail(10)[['Record ID','Amount','Amount_parsed']])

# Check duplicates
print('Unique Record IDs:', data_valid['Record ID'].nunique())
print('Total sum:', data_valid['Amount_parsed'].sum())
